def couple_key(name):   # frozen copy of ops.models.couple_key at the time of this migration
    s = (name or "").lower().replace("&", " and ").replace("+", " and ")
    s = re.sub(r"[^a-z0-9\u0900-\u097f]+", " ", s)
    return " ".join(w for w in s.split() if w not in ("and", "weds", "w")) or (name or "").strip().lower()


def group_existing_films(apps, schema_editor):
    """Put every film already in the portal under its couple: same agency + same couple
    name (ignoring case, '&' vs 'and', punctuation) = one couple. Nothing to re-enter."""
    Project = apps.get_model("ops", "Project")
    Couple = apps.get_model("ops", "Couple")
    groups = defaultdict(list)
    for p in Project.objects.all().only("id", "agency_id", "couple"):
        groups[(p.agency_id, couple_key(p.couple))].append(p)
    for (agency_id, key), films in groups.items():
        name = Counter(" ".join(f.couple.split()) for f in films).most_common(1)[0][0]
        c = Couple.objects.create(agency_id=agency_id, key=key, name=name)
        Project.objects.filter(id__in=[f.id for f in films]).update(client=c)


